        <div class="col-md-3"><label for="estado" class="form-label">Estado</label><select id="estado" name="estado" class="form-select"><option value="">Todos</option><?php foreach (TicketValidation::STATES as $value => $label): ?><option value="<?= $value ?>" <?= ($filters['estado'] ?? '') === $value ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></div>
        <div class="col-md-3"><label for="prioridad" class="form-label">Prioridad</label><select id="prioridad" name="prioridad" class="form-select"><option value="">Todas</option><?php foreach (TicketValidation::PRIORITIES as $value => $label): ?><option value="<?= $value ?>" <?= ($filters['prioridad'] ?? '') === $value ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></div>
        <div class="col-md-4"><label for="categoria_id" class="form-label">Categoría</label><select id="categoria_id" name="categoria_id" class="form-select"><option value="">Todas</option><?php foreach ($categories as $category): ?><option value="<?= (int) $category['id'] ?>" <?= (string) ($filters['categoria_id'] ?? '') === (string) $category['id'] ? 'selected' : '' ?>><?= View::escape($category['nombre']) ?><?= !$category['activa'] ? ' (inactiva)' : '' ?></option><?php endforeach; ?></select></div>
        <?php if (Auth::user()->role === 'administrador'): ?>
        <div class="col-md-4"><label for="agente_id" class="form-label">Agente actual</label><select id="agente_id" name="agente_id" class="form-select"><option value="">Todos</option><option value="sin_asignar" <?= ($filters['agente_id'] ?? '') === 'sin_asignar' ? 'selected' : '' ?>>Sin asignar</option><?php foreach ($users as $user): ?><option value="<?= (int) $user['id'] ?>" <?= (string) ($filters['agente_id'] ?? '') === (string) $user['id'] ? 'selected' : '' ?>><?= View::escape($user['nombre']) ?> (<?= View::escape($user['rol']) ?>)</option><?php endforeach; ?></select></div>
        <div class="col-md-4"><label for="solicitante_id" class="form-label">Solicitante</label><select id="solicitante_id" name="solicitante_id" class="form-select"><option value="">Todos</option><?php foreach ($users as $user): ?><option value="<?= (int) $user['id'] ?>" <?= (string) ($filters['solicitante_id'] ?? '') === (string) $user['id'] ? 'selected' : '' ?>><?= View::escape($user['nombre']) ?></option><?php endforeach; ?></select></div>
        <?php endif; ?>
    </div><div class="mt-3"><button class="btn btn-primary" type="submit">Aplicar filtros</button><a class="btn btn-outline-secondary ms-2" href="<?= View::escape($basePath) ?>">Limpiar</a></div>
