<div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><caption class="visually-hidden"><?= View::escape($title) ?></caption><thead><tr><th scope="col">Código y título</th><th scope="col">Categoría</th><th scope="col">Prioridad</th><th scope="col">Estado</th><th scope="col">Solicitante / agente</th><th scope="col">Creación</th><th scope="col">Acción</th></tr></thead><tbody>
<?php foreach ($list['rows'] as $row): ?><tr><td><strong><?= View::escape(Dates::code((int) $row['id'])) ?></strong><br><?= View::escape($row['titulo']) ?></td><td><?= View::escape($row['categoria_nombre']) ?></td><td><?= View::escape(TicketValidation::PRIORITIES[$row['prioridad']]) ?></td><td><span class="badge state-<?= View::escape($row['estado']) ?>"><?= View::escape(TicketValidation::STATES[$row['estado']]) ?></span></td><td><?= View::escape($row['solicitante_nombre']) ?><br><small class="text-secondary"><?= View::escape($row['agente_nombre'] ?? 'Sin asignar') ?></small></td><td><?= View::escape(Dates::local($row['created_at'])) ?></td><td><a class="btn btn-sm btn-outline-primary" href="/tickets/detalle?id=<?= (int) $row['id'] ?>" aria-label="Ver <?= View::escape(Dates::code((int) $row['id'])) ?>">Ver detalle</a></td></tr><?php endforeach; ?>
<?php if ($list['rows'] === []): ?><tr><td colspan="7" class="p-4 text-secondary">No hay tickets que coincidan con esta lista y sus filtros.</td></tr><?php endif; ?>
